 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Color, SRGBColorSpace } = ctx.THREE;

  const colors = {
    ink: config?.intent?.visualSpec?.colors?.ink ?? '#16161d',
    paper: config?.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
    accent: config?.intent?.visualSpec?.colors?.accent ?? '#ff2a38',
    surface: config?.intent?.visualSpec?.colors?.surface ?? '#0b0b10'
  };

  const width = 5.6;
  const height = 0.7;
  const accent = new Color(colors.accent);
  const surface = new Color(colors.surface);

  const root = new Group();
  root.name = config?.id ?? 'hub-collection-row';

  const rowGeo = new PlaneGeometry(width, height);
  const rowMat = new MeshBasicNodeMaterial({ color: surface, transparent: true });
  const row = new Mesh(rowGeo, rowMat);
  row.name = 'row-panel';
  root.add(row);

  const borderGeo = new PlaneGeometry(width + 0.08, height + 0.08);
  const borderMat = new MeshBasicNodeMaterial({ color: accent, transparent: true, opacity: 0 });
  const border = new Mesh(borderGeo, borderMat);
  border.name = 'row-border';
  border.position.z = -0.02;
  root.add(border);

  const dividerGeo = new PlaneGeometry(0.02, height * 0.55);
  const dividerMat = new MeshBasicNodeMaterial({ color: accent, transparent: true, opacity: 0.45 });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.name = 'row-divider';
  divider.position.set(0.9, 0, 0.01);
  root.add(divider);

  const timelines = new Set();
  function track(tl) {
    timelines.add(tl);
    tl.eventCallback('onComplete', () => timelines.delete(tl));
  }

  function lift(active) {
    const zTarget = active ? 0.15 : 0;
    track(gsap.to(row.position, {
      z: zTarget,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: true
    }));
    track(gsap.to(borderMat, {
      opacity: active ? 0.9 : 0,
      duration: 0.25,
      ease: 'power2.out',
      overwrite: true
    }));
  }

  function press(active) {
    const s = active ? 0.97 : 1;
    track(gsap.to(row.scale, {
      x: s,
      y: s,
      z: 1,
      duration: active ? 0.12 : 0.2,
      ease: active ? 'back.out(1.7)' : 'power2.out',
      overwrite: true
    }));
  }

  const handlers = {
    pointerenter: () => lift(true),
    pointerover: () => lift(true),
    hover: () => lift(true),

    pointerleave: () => {
      lift(false);
      press(false);
    },
    pointerout: () => {
      lift(false);
      press(false);
    },

    pointerdown: () => press(true),
    pointerup: () => press(false),

    click: () => {
      ctx.emit('hub-collection.select', { id: config?.id });
    }
  };

  root.userData.handlers = handlers;

  const imageUrl = config?.imageUrl ?? config?.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (root.userData._cleaned || !tex) return;
      tex.colorSpace = SRGBColorSpace;
      rowMat.colorNode = texture(tex, uv());
      rowMat.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    root.userData._cleaned = true;
    timelines.forEach((tl) => { try { tl.kill(); } catch {} });
    timelines.clear();
    rowMat.dispose();
    borderMat.dispose();
    dividerMat.dispose();
    rowGeo.dispose();
    borderGeo.dispose();
    dividerGeo.dispose();
  };

  return root;
};
